def transform(grid):
    g = np.array(grid)
    bg = background(g)
    H, W = g.shape
    # group full single-colour non-background columns by colour
    bycol = {}
    for x, c in dividers(g)["cols"]:
        if c != bg:
            bycol.setdefault(c, []).append(x)

    def split(xs):
        bounds = []
        start = 0
        for x in sorted(xs) + [W]:
            if x > start:
                bounds.append((start, x - 1))
            start = x + 1
        return bounds

    # the divider colour is the one whose columns cut the grid into equal-width panels
    best = None
    for c, xs in bycol.items():
        b = split(xs)
        widths = {x1 - x0 + 1 for x0, x1 in b}
        if len(b) > 1 and len(widths) == 1:
            if best is None or len(b) > len(best):
                best = b
    bounds = best if best is not None else [(0, W - 1)]

    pw = bounds[0][1] - bounds[0][0] + 1
    out = np.full((H, pw), bg, dtype=int)
    emit(out, "Allocate an empty panel-sized canvas filled with the background colour.")
    for k, (x0, x1) in enumerate(bounds):
        panel = g[:, x0:x1 + 1]
        objs = objects(panel, bg=bg)
        objs.sort(key=lambda o: (min(c[1] for c in o["cells"]), min(c[0] for c in o["cells"])))
        if k >= len(objs):
            continue
        o = objs[k]
        for (y, x) in o["cells"]:
            if x < pw:
                out[y, x] = o["colour"]
        emit(out, f"Panel {k+1}: take its object number {k+1} counted from the left (colour {o['colour']}) and stamp it at the same local position.")
    emit(out, "Final combined panel.")
    return out
